def factorize(n: int) -> List[int]:
    def generate_prime_factors(num):
        factors = []
        divisor = 2
        while divisor <= num:
            if num % divisor == 0:
                factors.append(divisor)
                num = num / divisor
            else:
                divisor += 1
        return factors

    prime_factors = generate_prime_factors(n)
    prime_factors.sort()

    result = []
    for factor in prime_factors:
        count = prime_factors.count(factor)
        result.extend([factor] * count)

    return result

